export type CompanionRefusal = "FetchFailed" | "NoBaseCommit" | "BranchExists" | "WorktreeRefused";

/**
 * And of taking one away.
 *
 * No *no such companion*: a row that is not there is the state the press asked
 * for, so it comes back as [`CompanionRemoved::Removed`] like any other.
 */
export type CompanionRemoved = "Removed" | "NoSuchConversation" | "NotDrafting";

/**
 * One companion of a Conversation the steer opens up: read-only until now,
 * read-write from here.
 *
 * **Two fields rather than four, and the missing two are the point.** There is
 * no mode, because there is one direction — a row that could carry read-only
 * would be a row that could take back what a session was given. And there is
 * no base: what the upgrade comes off is the base already on the row, picked
 * while the Conversation drafted, re-resolved at this moment because the
 * companion is joining the work now.
 */
export type CompanionUpgrade = { repo_id: number, 
/**
 * What the branch cut in it is to be called, or empty for *mirroring* —
 * the Conversation's own branch name, exactly as at draft time.
 */
branch: string, };

/**
 * One companion repo of a Conversation: which Repo, how far into it a session
 * may reach, and what its checkout comes off.
 *
 * The Repo in the shape the Repo list sends one, for [`ConversationView`]'s
 * reason: the card names it and links nowhere else, and a second shape for a
 * Repo would be a second opinion about what one is.
 */
export type CompanionView = { repo: RepoEntry, mode: CompanionMode, 
/**
 * The branch this companion's checkout comes off, where the human named
 * one. `null` is the same rule the Conversation's own base follows: that
 * repository's default branch, as it stands when grilling starts.
 */
base_ref: string | null, 
/**
 * What a read-write companion's branch will be called, or empty for
 * *mirroring* — the Conversation's own branch name, followed as it is
 * renamed. Empty on a read-only companion as well, there being no branch
 * to name: its checkout is detached at the commit the base resolved to.
 */
branch: string, 
/**
 * Where this companion was checked out, once grilling has made its
 * worktree.
 *
 * `null` while the Conversation drafts and again once it is closed, which
 * is the Conversation's own worktree's rule: a companion has a directory
 * for exactly as long as the work does.
 */
worktree: Worktree | null, 
/**
 * The commit its base resolved to when that checkout was made.
 *
 * What a read-only companion is detached at, and what a read-write one's
 * branch was cut from. Kept beside [`Self::base_ref`] rather than instead
 * of it, because the two say different things: the ref is the *name* the
 * human picked and what a rename or a steer would follow, and this is where
 * that name stood at the one moment it mattered.
 *
 * `null` wherever [`Self::worktree`] is, and on a checkout made before
 * Verkstead kept the commit.
 */
base_commit: string | null, };

/**
 * How a merge conflict between a pull request and its base branch is resolved.
 *
 * Two words for two ways of putting the base's work on a branch that has
 * diverged from it, and what tells them apart is what happens to the commits
 * already pushed: a merge leaves every one of them where it is, and a rebase
 * writes them again and has to be force-pushed — which rewrites what reviewers
 * have read and breaks anything stacked on the branch.
 *
 * Which is why the page says so beside the choice rather than leaving it to be
 * found later, and why merge is what nobody choosing anything gets.
 */
export type ConflictResolution = "Merge" | "Rebase";

/**
 * How one Repo is to resolve a conflict from now on, which is the one thing
 * there is to *say* to a registered Repo besides taking it away.
 *
 * `null` takes the override back rather than writing the global's word down:
 * what *use the global setting* means is that this Repo says nothing, and a
 * Repo holding a copy of today's global would go on holding it after the global
 * moved.
 */
export type ConflictResolutionEdit = { resolution: ConflictResolution | null, };

/**
 * And what became of archiving one: putting a Closed Conversation away, so the
 * sidebar stops drawing it.
 *
 * Reversible, which is why nothing here is confirmed and why the refusals are
 * so mild: the worst of them says the human asked for something that is already
 * true.
 */
export type ConversationArchived = "Archived" | "AlreadyArchived" | "NotClosed" | "NoSuchConversation";

/**
 * What became of closing one.
 */
export type ConversationClosed = "Closed" | "AlreadyClosed" | "NoSuchConversation";

/**
 * One row of the conversations sidebar.
 *
 * The branch is the row's name where somebody has settled on one: a
 * Conversation has no title of its own, and of what it does have the branch is
 * the short line a human chose. A draft nobody has named carries a name
 * Verkstead invented instead, and reads *Draft* — see [`Self::branch_named`].
 *
 * Where it has got to is drawn rather than worded — a turning ring for a
 * session getting on with it, the same ring empty for one that has gone quiet,
 * a dot for a Conversation that wants answering or has news on it, a dotted
 * border for a draft and a dimmed card for work that has stopped. Which is why
 * the facts below are facts and not one collapsed verdict: the row says what is
 * true of the Conversation, and which mark that comes out as is the one rule
 * the viewer keeps.
 */
export type ConversationEntry = { id: number, branch: string, 
/**
 * Whether that name is one somebody settled on, rather than the one
 * Verkstead prefilled the record with.
 *
 * A name nobody chose says nothing about the work, so a draft carrying one
 * is drawn as *Draft* and the name itself is drawn nowhere — in the title
 * and in what is read aloud alike. Two drafts against one Repo reading the
 * same is what two drafts are. Once the work has started the branch is a
 * fact rather than a plan, and a fact is named wherever it is reported.
 */
branch_named: boolean, 
/**
 * And whether the name it is carrying is still the first session's to
 * replace.
 *
 * The work starting is not what makes an invented name worth drawing: the
 * first session is told to switch the branch to something the Brief is
 * about, and until it has the name says no more than it did while this was
 * a draft. So the row goes on reading *Draft* while this is true, and reads
 * the branch the moment it is not — the session renamed it, or the session
 * ended and the name it left is the one this is called by.
 *
 * Always `false` where the human typed a name: there was never anything to
 * wait for.
 */
naming: boolean, 
/**
 * What the Repo this Conversation is against is called.
 */
repo: string, state: Lifecycle, 
/**
 * Whether a session is running on this Conversation right now.
 *
 * The server's own registry of running processes and nothing else, so a
 * server that restarted says no about work it is no longer doing.
 */
working: boolean, 
/**
 * And whether that session has stopped printing — the same quiet the
 * agent-output row's mark is drawn from, said here so that a card and the
 * row it opens tell the same truth about the same session.
 *
 * Always `false` where nothing is working, which is what keeps the two a
 * pair rather than a contradiction: idle is a thing a *running* session
 * is. Which mark it comes out as is the viewer's, and the rule there is
 * unchanged — waiting still wins over both.
 */
idle: boolean, 
/**
 * Whether something about this Conversation is waiting on the human: an ask
 * left open, or driving that has stopped.
 *
 * Folded from every source before it leaves, so the viewer holds no list of
 * them. A Draft is never one of them: it is drawn as a draft, and that is
 * the whole of what a draft has to say.
 */
waiting: boolean, 
/**
 * Whether this one is a wrap-up that has narrowed to its checks: the review
 * and the comments settled, the checks not, and nothing running on it.
 *
 * A derived condition of Wrapping rather than a state, which is why it sits
 * beside `state` the way *blocked on you* does rather than in it. Nothing
 * is stored for it: it is the wrap-up's own settle facts read a particular
 * way, folded here so the row does not have to.
 *
 * The row draws no state in words, so what this comes out as is the label
 * read aloud — *Waiting on checks* where the plain state word would be.
 */
waiting_on_checks: boolean, 
/**
 * Whether Verkstead has told the human something about this Conversation
 * that they have not looked at yet.
 *
 * One thing writes it: the wrap-up that carries a Conversation to Done and
 * pushes the news to the devices, in the same breath as the push. A
 * milestone nobody was watching happen is what a mark saying *look here*
 * is for, and a Done the human steered to themselves is what it is not.
 *
 * Beside `waiting` rather than folded into it, because the row draws one
 * disc for the two and says which of them it is in the label read aloud:
 * *something wants you* against *there is news here*. Cleared by opening
 * the Conversation, which the browser says in a call of its own.
 */
unseen: boolean, };

/**
 * What became of submitting one.
 *
 * Named the way [`GrillingStarted`]'s refusals are, and nothing here is about
 * the state the Conversation was in: the human has looked at the work and said
 * where it goes, so the source is not something to be refused for. What is left
 * to be wrong about is the *target* — a state whose work cannot be set going
 * from what the record holds.
 */
export type ConversationSteered = "Steered" | "NoSuchConversation" | "NoPullRequest" | "NoInstruction" | "NoFollowUpBrief" | "EmptyBrief" | "NoPairing" | "NoSuchProfile" | "NoSuchModel" | "NoBaseCommit" | "WorktreeRefused" | "NoSuchCompanionRepo" | { "Companion": { 
/**
 * The Repo's registered name.
 */
repo: string, why: SteerCompanionRefusal, } };

/**
 * What became of pressing Stop or Force stop.
 *
 * One answer for both presses, because they ask for the same thing and differ
 * only in what they will wait for: the run is to stop, and nothing is to be
 * started for this Conversation until Resume is pressed. [`Stopped`] and
 * [`Stopping`] are the two ways that is now true — see each.
 *
 * Named the way [`Resumed`]'s refusals are, and for the same reason: a press
 * that quietly did nothing would leave the human watching a run they thought
 * they had stopped.
 *
 * [`Stopped`]: ConversationStopped::Stopped
 * [`Stopping`]: ConversationStopped::Stopping
 */
export type ConversationStopped = "Stopped" | "Stopping" | "AlreadyStopped" | "NotDriven" | "NoSuchConversation";

/**
 * And what became of taking one back out, which is the way back from it.
 *
 * One refusal fewer than archiving has: there is no state a Conversation can
 * be in that is the wrong one to put back on the list.
 */
export type ConversationUnarchived = "Unarchived" | "NotArchived" | "NoSuchConversation";

/**
 * One Conversation, whole: what it is attached to, what the human has settled
 * about it, and everything that has happened to it.
 */
export type ConversationView = { id: number, 
/**
 * The Repo, in the shape the Repo list already sends one — the workbench
 * shows the same three facts about it, and a second shape for the same
 * thing would be a second opinion about what a Repo is.
 */
repo: RepoEntry, branch: string, 
/**
 * Whether that name is one somebody settled on, rather than the one
 * Verkstead prefilled the record with — see
 * [`ConversationEntry::branch_named`], which is the same fact drawn as a
 * title.
 *
 * What the pane does about a draft that says no: the header reads *Draft*,
 * and the setup card's branch field stands empty under the placeholder
 * saying what leaving it empty means. The name itself is drawn nowhere.
 */
branch_named: boolean, 
/**
 * And whether the name it is carrying is still the first session's to
 * replace — see [`ConversationEntry::naming`], which is the same fact drawn
 * as a title.
 *
 * The header keeps reading *Draft* through it, the setup card having gone
 * by then. What the card would have shown is settled: the branch is cut and
 * the field is frozen, whatever the name on it turns out to be.
 */
naming: boolean, 
/**
 * The commit the work will branch from, where the human overrode the rule.
 * `null` is the rule itself: the default branch's tip, as it stands when
 * grilling starts — which is why there is no value here to show instead.
 */
base_commit: string | null, 
/**
 * The other registered Repos this Conversation works alongside, by name.
 *
 * Empty is the ordinary Conversation. Beside the branch and the base
 * because it is the same kind of fact — what the work is configured with —
 * and settled in the same place and at the same moment: the setup card
 * while the Brief drafts, frozen when grilling starts.
 */
companions: Array<CompanionView>, state: Lifecycle, 
/**
 * The Profile and model the grilling session will run under, whole rather
 * than by id: the pane says what they are, and whether the Profile is
 * still runnable.
 *
 * One of the two roles the picker offers a row that runs no session for,
 * so this says which of three the human picked rather than whether they
 * picked at all. A Conversation that picked *no grilling* is not grilled:
 * its Brief goes straight to an inline implementation.
 */
grilling_pairing: PickedView, 
/**
 * And the ones the implementation will run under. Chosen separately
 * because it is genuinely a separate account and model.
 */
implementation_pairing: PairingView | null, 
/**
 * And what the wrap-up's review session will run under, chosen separately
 * again: reviewing is a fresh set of eyes on what was built.
 *
 * The other role the picker offers a row that runs no session for, so this
 * says which of three the human picked rather than whether they picked at
 * all.
 */
review_pairing: PickedView, 
/**
 * Whether everything needed before the work will start is settled: every
 * role picked — a Pairing complete and no Profile broken, or the row that
 * runs no session — a Brief with something in it, and a Conversation still
 * drafting.
 *
 * The server's rule rather than something the page works out from the
 * fields around it. Every one of the refusals is checked again when the
 * button is pressed — this is what decides whether to offer the button, and
 * what it says is true only as of the moment it was read.
 */
ready_to_grill: boolean, 
/**
 * Whether to warn, where the work is started from, that this repository's
 * dependency compiles will not be cached.
 *
 * True on three things at once: the Repo is a Cargo workspace — a
 * `Cargo.toml` at its root — the shared Rust build cache is switched on,
 * and the server found no sccache to compile through. Then a session's
 * crate downloads are shared and its dependencies are compiled from
 * scratch every time, which is a slow build rather than a broken one — so
 * it is a note above the button, not a refusal on it.
 *
 * The server's rule rather than three fields for the page to combine, for
 * the reason [`ConversationView::ready_to_grill`] is one: two of the three
 * are facts about the server that nothing else on this payload carries.
 */
compiles_uncached: boolean, 
/**
 * Whether there is driving to start again: the Conversation is in a state
 * something ought to be driving, and nothing is.
 *
 * What decides whether Resume is offered, and the server's rule rather
 * than something the page works out from the fields around it — *driven*
 * is a register of tasks that are running, and a page cannot see one.
 * Every refusal is checked again when the button is pressed; this says
 * only that it was worth offering as of the moment it was read.
 *
 * A question about a process as much as about the record, so a restarted
 * server reads every Conversation it left mid-run as one to resume —
 * which each of them is.
 */
ready_to_resume: boolean, 
/**
 * And whether there is driving to stop: the Conversation is in a state
 * something ought to be driving, and it has not stopped.
 *
 * What decides whether Stop and Force stop are offered. Not the mirror of
 * [`ready_to_resume`]: a Conversation between one step and the next has
 * both, because nothing is running now and the run is going to launch
 * something the moment it can. A quiet Conversation is one to stop as much
 * as a busy one.
 *
 * Force stop is offered where this and [`working`] are both true — the
 * stop that ends a session is worth offering only where there is one.
 *
 * [`ready_to_resume`]: ConversationView::ready_to_resume
 * [`working`]: ConversationView::working
 */
ready_to_stop: boolean, 
/**
 * And whether a stop has already been asked for and is waiting for the step
 * the run is on to finish.
 *
 * What takes **Stop** off the menu, the press having been made: it is
 * recorded, the run halts the moment the step lands, and a row still
 * offering it would be Verkstead asking for a decision it already has.
 * Force stop is left where it is — it is the escalation from here, and the
 * one thing a human who has changed their mind about waiting can still
 * press.
 *
 * Beside [`ready_to_stop`] rather than folded into it, because the two say
 * different things: that one is *there is a run to stop*, which is what
 * draws Force stop, and this is *and you have already said so*.
 *
 * [`ready_to_stop`]: ConversationView::ready_to_stop
 */
stop_asked: boolean, 
/**
 * And whether a steer into Implementing has anything to carry on: the
 * branch holds a backlog with work left in it, or a roadmap it has
 * written.
 *
 * What decides whether the steer modal offers *carrying on* — the target
 * itself is offered on every Conversation there is, because an instruction
 * can always be written. Where this is false the instruction is the whole
 * of what that target can be, so the modal requires one.
 *
 * The server’s rule rather than something the page works out from the
 * fields around it: what stands is a reading of the Worktree as it is now,
 * which a page cannot make. Read the same way everything else pinned to
 * the Timeline is.
 *
 * **A Worktree that has gone is not a branch holding nothing**, and this is
 * true there. There is no directory to read, and the steer checks one out
 * of the branch before anything runs in it — so a Conversation stuck behind
 * a deleted directory is offered the carrying on its branch may well hold,
 * and what decides it in the end is the relaunch that reads the directory
 * the steer has just made.
 *
 * Checked again when the modal is submitted, as every refusal here is;
 * this says only that it was worth offering as of the moment it was read.
 */
ready_to_continue: boolean, 
/**
 * What this Conversation is adopting, where it is adopting anything.
 *
 * `null` is the ordinary Conversation, which begins with a Brief and a
 * grilling. Anything else is one started from the abandoned-roadmaps
 * notice, and it is what puts the page on the adoption shape: the roadmap
 * and its stage named, both Profiles and the base commit to fix, and one
 * Adopt press — no Brief to write and no grilling to start.
 */
adopting: AdoptionView | null, 
/**
 * The worktree the grilling was given to work in, once there is one.
 *
 * `null` both before grilling starts and after closing — the two ways a
 * Conversation has none, which are the same fact about it.
 */
worktree: Worktree | null, 
/**
 * The latest pick: how the human most recently said the work should be
 * built, on a proposal Set of this Conversation's.
 *
 * `null` until a proposal has been put to them and picked on. What the page
 * *draws* of the choice is the answered Set on the Timeline, which is where
 * it was made; this is the fact about the Conversation itself.
 */
direction: Direction | null, 
/**
 * Which Event the Conversation is blocked on, or `null` where nothing is
 * stopping it.
 *
 * The Event id and not a flag, so that the Notice a run stopped at can be
 * marked where it stands on the record — a Timeline is long by the time a
 * run gets far enough to stop, and the status button at the head of it
 * saying the work has stopped is half an answer without somewhere to read
 * why.
 *
 * Being stopped is a condition of an active state and never a state of its
 * own, which is why this sits beside `state` rather than in it.
 *
 * Set for every stop, however it stopped. Which word the status button
 * says over it is `stopped_by_hand` below; the Notice is the same Notice
 * either way, a stop the human has to find being no different on the
 * record from a stop they made themselves.
 */
blocked_on: number | null, 
/**
 * Whether that stop is the human's own press, or a row from before the
 * two were told apart and read as one.
 *
 * Which word the status button says over the stop, decided here rather
 * than in the browser: `false` is the accented one — Verkstead pulled the
 * brake, or a crash took the driver away, so the Conversation is *Waiting
 * on you*, or *Blocked* where somehow it is not — and `true` is the quiet
 * *Stopped*, which says nothing about anybody waiting. The sidebar's disc
 * follows the same rule from its own end of the wire, where the row's
 * `waiting` has already folded it in.
 *
 * `false` where nothing has stopped, which is the ordinary Conversation:
 * there is no word to choose between.
 */
stopped_by_hand: boolean, 
/**
 * Whether something about this Conversation is waiting on the human: an ask
 * left open, or driving that has stopped without them.
 *
 * The same fact the sidebar row carries — see [`ConversationEntry::waiting`]
 * — folded by the same rule in the same place, so the row and the page it
 * opens can never come to disagree about the one Conversation. What the
 * page does with it is its own: the row draws a disc, and the head of the
 * Timeline draws the status word in the accent colour.
 *
 * A Draft is never one of them, and neither is a Closed Conversation: the
 * first is drawn as a draft and the second has nothing left to want.
 */
waiting: boolean, 
/**
 * Whether the wrap-up has narrowed to its checks: the review answered, the
 * comments dealt with, the checks alone outstanding, and nothing running in
 * the Worktree.
 *
 * What the *Waiting on checks* label is drawn from, and a condition of
 * Wrapping rather than a state of its own — the precedent is `blocked_on`
 * above, and this sits beside `state` for the same reason. Nothing is
 * stored for it: it is the settle facts and the register read together, at
 * the moment the page was read.
 *
 * A flag rather than an Event id, because unlike a stop there is nothing to
 * go and look at and nothing to do about it — the Notice saying so is on
 * the record where it happened, and the label is a label.
 *
 * `false` in every state but Wrapping, which is where the condition is
 * derived from and the only place it can hold.
 */
waiting_on_checks: boolean, 
/**
 * What the stop shows about the account that ran out coming back, and
 * `null` on every stop that is not a usage window's — which is nearly all
 * of them, and every Conversation that has not stopped.
 *
 * Words for the status button's second line, where what is running is
 * otherwise said, rather than a moment anything acts on: no stop resumes
 * itself, so what a stopped run waits for is a press whatever stopped it.
 * The one thing that tells a run stopped by an exhausted window from a run
 * stopped by anything else — same card, same status, same row to press.
 *
 * As the session printed it, because the wording is the backend's: `3pm`
 * stays `3pm`, which is what somebody looks at their own clock for.
 */
resets: string | null, 
/**
 * Whether a session is registered for this Conversation as of this read.
 *
 * The same fact the sidebar draws its working indicator from, said here
 * because the Timeline has its own use for it: Force stop is offered
 * exactly where something is running, and the states it is offered in are
 * the ones a session may or may not be running in.
 *
 * A question about a process rather than about the record, so it is true
 * only as of the moment it was read — and a restarted server has no
 * sessions at all, so every Conversation then reads as not working, which
 * is what each of them is.
 */
working: boolean, 
/**
 * And whether any driver of Verkstead's own is registered for it as of
 * this read: the runner working a backlog, the driver following an inline
 * run or a roadmap, one of the watchers a wrap-up has going — see the
 * server's own drivers register.
 *
 * The same register [`ready_to_resume`] is decided against, reported raw
 * rather than judged: this says what *is* driving and that one says what
 * ought to be. So it is a plain `false` wherever nothing holds a
 * registration, including the states nothing is supposed to be driving —
 * a Closed Conversation is not one being driven, whatever the resume rule
 * makes of it.
 *
 * Read for the reason [`working`] is, one register along, and true only as
 * of the moment it was read. The pair is what says a Conversation has gone
 * quiet all the way through: no session running *and* nothing left holding
 * it. Which is a stronger thing than the first alone, because a driver
 * lets go only once its task has ended — so a watcher that is off here has
 * finished its last call to the outside world rather than merely started
 * it.
 *
 * [`ready_to_resume`]: ConversationView::ready_to_resume
 * [`working`]: ConversationView::working
 */
driven: boolean, 
/**
 * Oldest first, which is reading order and puts the Brief at the top.
 */
timeline: Array<TimelineEvent>, 
/**
 * Whether the human has put this Conversation away — see
 * [`ConversationArchived`].
 *
 * What the actions menu offers Unarchive by, in the place Archive stands
 * in on a Closed Conversation that is still on the list. Nothing else on
 * the page turns on it: an archived Conversation is drawn exactly as it
 * was, because being off the sidebar is the whole of what archiving does.
 */
archived: boolean, 
/**
 * The Events that stay in view rather than scrolling past with the record.
 *
 * Apart from the Timeline rather than in it, because that is what pinning
 * *is*: the list is a record of moments, and each of these is the current
 * state of something the work is against. Empty is the ordinary case — a
 * Conversation with no backlog has nothing to pin.
 */
pinned: Array<PinnedEvent>, 
/**
 * Where the latest share of this Conversation was published, and when.
 *
 * `null` on every Conversation nobody has published one of, which is most
 * of them: downloading a share leaves no trace, and this is only about the
 * one that was put somewhere a link can reach.
 *
 * Replaced rather than added to. Publishing again is a fresh snapshot of a
 * Conversation that has moved on, so what the workbench draws is where to
 * send somebody *now* — see the store's `shares`, which says what becomes
 * of the link it replaced.
 */
shared: ShareView | null, };

/**
 * The Diff as the browser receives it: the HTML the server rendered, and the
 * path of each file in it, in Diff order — `paths[0]` is what `#diff-1` shows.
 *
 * The two travel together rather than as two fields on the Set, because they
 * describe the same thing and the table of contents is built from both: the
 * nav names the folds from the paths and jumps by their positions, so a nav
 * out of step with the markup would jump to the wrong file. Reading the paths
 * back out of the rendered HTML instead would mean shipping a parser to do it
 * with, and would make the nav a description of the page rather than of the
 * Set.
 */
export type DiffView = { html: string, paths: Array<string>, };

/**
 * One of the three ways the work can be built.
 *
 * Named on the wire in the words the design uses for them, so a Set is
 * readable as written: `inline`, `task-list`, `roadmap`.
 */
export type Direction = "inline" | "task-list" | "roadmap";

/**
 * What became of starting a Conversation grilling.
 *
 * Every refusal is named rather than collapsed into one, because each of them
 * is something different for the human to go and do: choose a Profile, write a
 * Brief, pick another commit, deal with a branch that is already there. A
 * single "cannot start" would leave them guessing which.
 *
 * A companion repo can fail in four of the same ways the Conversation's own
 * does, and which repository it was is the thing the human needs — so those
 * four are carried together under [`GrillingStarted::Companion`], named for
 * the Repo they are about. Nothing gates the button on a companion: the
 * configuration is always complete, so refusal at the start is the whole story.
 */
export type GrillingStarted = "Started" | "NoSuchConversation" | "NotDrafting" | "NoGrillingProfile" | "NoImplementationProfile" | "NoReviewProfile" | "ProfileBroken" | "EmptyBrief" | "FetchFailed" | "NoBaseCommit" | "BranchExists" | "WorktreeRefused" | { "Companion": { 
/**
 * What the companion Repo is called, which is what the human picked it
 * by and what they will go and look at.
 */
repo: string, why: CompanionRefusal, } };

/**
 * The handoff document as the page receives it.
 *
 * HTML alone, unlike the Brief, which travels as its source as well: the Brief
 * is the one document on this wire the human edits, and this one nobody does.
 * It is the agent's account of what was settled, fixed at the moment the
 * grilling ended.
 */
export type HandoffEvent = { id: number, 
/**
 * When it reached the Timeline, RFC 3339.
 */
at: string, 
/**
 * Rendered and sanitized by the server on the way out, as every piece of
 * agent markdown on this wire is.
 */
html: string, };

/**
 * One class of comment nobody wants an agent addressing.
 *
 * Two patterns, either of which may be empty for *no constraint on that part*
 * — strings rather than optionals, and empty for nothing, the way the author's
 * two halves are: the row on the page holds a box either way, and clearing one
 * is how the constraint is taken off.
 *
 * Regular expressions in the regex crate's syntax, matched anywhere in their
 * text rather than against the whole of it, and case-sensitive unless the
 * pattern opens with `(?i)`. The author's is matched against the login of
 * whoever wrote the comment and the body's against the markdown as it was
 * written.
 */
export type IgnoreRule = { author: string, body: string, };

/**
 * What is to become of the ignore rules on a save.
 *
 * An action rather than a value, for the reason [`TokenEdit`] is one and not
 * the same reason: nothing about a rule is secret, but the rules are the one
 * thing a save can be refused over, and a section that is not about them
 * should not be able to have its own save turned down by a pattern it never
 * showed anybody.
 */
export type IgnoredCommentsEdit = "Keep" | { "Set": { rules: Array<IgnoreRule>, } };

/**
 * Where a Conversation has got to.
 *
 * The whole ladder, though only the first two are reachable yet: the states are
 * the domain's, and the page says which one a Conversation is in rather than
 * assuming the only one it can currently be.
 */
export type Lifecycle = "Draft" | "Grilling" | "Implementing" | "Wrapping" | "FollowUp" | "Done" | "Closed";

/**
 * What a Set still waiting on the human says about itself: whether an agent is
 * currently waiting on it, whether nothing is holding a wait any more, or
 * whether nothing ever was.
 *
 * Display state only (ADR-0001). A disconnected Set is still answerable and is
 * never withdrawn on its own — the CLI reconnects through transient drops, and
 * only a human may lock a Set whose agent is really gone.
 *
 * It is a verdict rather than a timestamp because the server has the clock and
 * the registry of held waits; the browser only draws what it is told.
 */
export type Liveness = "waiting" | "disconnected" | "deferred";

/**
 * What became of the human closing a Set unanswered.
 */
export type Locked = "Closed" | "AlreadyAnswered" | "AlreadyLocked" | "NoSuchSet";

/**
 * A Manual Task as the page receives it: what was asked for, and when.
 *
 * HTML alone, like the Notice beside it and unlike the Brief: it is a moment on
 * the record rather than a document anybody goes back and edits.
 */
export type ManualTaskEvent = { id: number, 
/**
 * When it was asked for, RFC 3339.
 */
at: string, 
/**
 * Rendered and sanitized by the server on the way out, as every piece of
 * markdown on this wire is.
 */
html: string, };

/**
 * And whether it merges into its base.
 *
 * The store's own word again, and two rather than GitHub's three for the reason
 * it keeps two: a GitHub that has not worked the answer out yet is *not known*,
 * and not knowing is the absence of this rather than a word in it — the same
 * card with no mark on it that a pull request nothing has asked about draws.
 */
export type Merging = "Cleanly" | "Conflicting";

/**
 * And one it did not.
 */
export type MissedOut = { number: number, repo: string | null, 
/**
 * What `gh` said about it, in its own words. A pull request that has gone
 * and one the token may not write on are two afternoons apart, and neither
 * is anything Verkstead can put right on the human's behalf.
 */
why: string, };

/**
 * A move as the page receives it: when, and to what.
 *
 * No rendered body, unlike the Brief — there is no markdown in a move. What the
 * Timeline draws is a sentence of the viewer's own making from the one state,
 * because the wording belongs to whoever is reading it rather than to the
 * record.
 */
export type MovedEvent = { id: number, 
/**
 * When it moved, RFC 3339.
 */
at: string, state: Lifecycle, };

/**
 * Starting one to adopt a roadmap with: which Repo, and which of its roadmaps.
 *
 * What the notice sends when a roadmap in it is clicked. The roadmap is named
 * by its directory under `docs/roadmaps/`, which is its identity here as
 * everywhere else — the stage is not sent, because which stage is next is the
 * roadmap's own answer at whatever commit the Conversation ends up branching
 * from.
 */
export type NewAdoption = { repo_id: number, roadmap: string, 
/**
 * The branch the roadmap was found on, where it was found on one — the
 * [`AbandonedRoadmap::base`] of the row that was clicked, carried back so
 * the Conversation starts fixed to it.
 *
 * Absent where the row came off the default branch, which is what a
 * Conversation with no base fixed already reads.
 */
base: string | null, };

/**
 * Which registered Repo to work alongside.
 *
 * The id and nothing else: everything a companion holds beyond which Repo it
 * is has a default worth having, and a press in a menu is one decision.
 */
export type NewCompanion = { repo_id: number, };

/**
 * Starting a Conversation: the Repo it is against, and nothing else.
 *
 * The branch name is not the browser's to send. It is prefilled randomly, and a
 * prefill the page invented would be one the server never saw — the record is
 * the server's from the moment it exists.
 */
export type NewConversation = { repo_id: number, };

/**
 * The order the human has just dragged the sidebar into: every Conversation
 * they can see, by id, top first.
 *
 * The whole list rather than the one row that moved, because the whole list is
 * what a drag produces and what the human is looking at when they let go. A
 * move said as *this one, to there* would have to be replayed against a list
 * the server might have added to since; a list said whole is simply what they
 * meant.
 */
export type NewOrder = { order: Array<number>, };

/**
 * A notice as the page receives it: what Verkstead did, and when.
 *
 * HTML alone, like the handoff and unlike the Brief: nobody edits it. Rendered
 * on the way out all the same, because a notice says which stage it started and
 * what the branch is called, and those are worth setting in a code span rather
 * than running into the prose around them.
 */
export type NoticeEvent = { id: number, 
/**
 * When it was said, RFC 3339.
 */
at: string, 
/**
 * Rendered and sanitized by the server on the way out, as every piece of
 * markdown on this wire is.
 */
html: string, };

/**
 * One thing that moved, said as briefly as it can be said.
 *
 * A page too old to know a kind treats it as everything having moved, which is
 * the behaviour every kind used to get — so a new kind is safe to add and an
 * old page stays correct against a newer server.
 */
export type Nudge = { "kind": "transcript", conversation: number, } | { "kind": "screen", conversation: number, } | { "kind": "commit", conversation: number, } | { "kind": "set", conversation: number, } | { "kind": "liveness", conversation: number, } | { "kind": "conversation", conversation: number, } | { "kind": "conversations" } | { "kind": "repos" } | { "kind": "profiles" };

/**
 * One Option as the page draws it: the number a Response answers by, its text
 * already rendered, and whether the agent recommended it.
 *
 * Its text is inline markup and nothing blockier, because an Option is one line
 * beside a radio and the whole row is the tap target: a paragraph or a list
 * emitted inside that label would split the row in two.
 */
export type OptionView = { n: number, 
/**
 * The text as inline HTML, rendered and sanitized by the server on the way
 * out.
 */
text_html: string, recommended: boolean, 
/**
 * This Option's row of the Answer Table, one cell per axis the question
 * declared, in that order, each already inline HTML. Empty wherever the
 * question declared no axes.
 *
 * Inline for the reason `text_html` is: the whole row is the tap target,
 * and a block in one of its cells would break the row apart.
 */
cells: Array<string>, };

/**
 * One of a Conversation's Pairings, as the page shows it: the Profile
 * whole, and the model paired with it.
 *
 * The Profile whole rather than by id because the pane says what it is and
 * whether it is still runnable — and the model beside it because a Pairing is
 * both halves, and either half alone is not something to launch a session
 * with.
 */
export type PairingView = { profile: ProfileEntry, 
/**
 * The model of that Profile's list this Conversation's sessions run on.
 *
 * `null` is a Profile chosen before pairings existed, which is not a
 * Pairing: the page draws it as nothing chosen, because while the
 * Conversation is drafting that is a choice to make again. One past
 * drafting keeps running on the model its Profile carried, which nothing
 * here has to say — its Pairings are fixed and there is no picking left.
 */
model: string | null, };

/**
 * Whether the server can see what an entry names, at the moment it was asked.
 *
 * Reported rather than refused: a save lands whatever it was told, so an entry
 * naming a directory nobody has made yet is something to say on the row rather
 * than something to turn a save down over. It is also how a nix install learns
 * that a path added here needs the installer to widen the unit's namespace
 * before it can do anything — the file says it, and the server cannot see it.
 */
export type PathResolution = "Resolves" | { "Unresolved": { why: string, } };

/**
 * Which of the two places an entry was said in.
 *
 * What decides whether the page will let it be edited: the installation's are
 * the unit's word or the command line's and are read-only wherever they are
 * drawn, and the settings' own are the human's to add to and take away.
 */
export type PathSource = "Installation" | "Settings";

/**
 * Every path Verkstead has been told about, from both sources at once: the
 * directories it may operate inside, and the extra directories a sandbox is
 * given beyond the surface every one of them has.
 *
 * Two lists rather than one, because they are two different permissions — a
 * Watched Path says where the human may point Verkstead, and a bind says what
 * a session may write in — and the page draws them apart for that reason.
 *
 * The installation's own entries come first in each list, and the settings'
 * follow in the order they were written down. That is the order the two were
 * decided in: a flag is said once when the machine is set up, and the file is
 * where somebody has been adding to it since.
 */
export type PathsView = { watched: Array<WatchedPathEntry>, 
/**
 * Every configured bind, the ones every sandbox gets and the ones one Repo
 * does together — see [`BindEntry::repo`], which is what says which of the
 * two an entry is.
 */
binds: Array<BindEntry>, };

/**
 * What a Conversation has settled about one of its roles, as the page shows
 * it: the Pairing its sessions run under, that the role runs none, or nothing
 * picked yet.
 *
 * Three rather than a nullable Pairing, because a picker offers *no grilling*
 * or *no review* as a row of its own: a Conversation that picked one is as
 * ready to start as one that picked a Pairing, and a page that could not tell
 * it from an empty picker would draw the placeholder over a settled choice.
 */
export type PickedView = "Nothing" | "Skipped" | { "Under": PairingView };

/**
 * An Event the Timeline keeps in view rather than letting scroll past.
 *
 * A fixed set — a task list, a stage list and a PR — and no manual pin or
 * unpin: what is pinned is decided by what kind of thing it is, so there is no
 * state here to flip and no route to flip it with. A tagged kind for the reason
 * [`TimelineEvent`] is one: what gets drawn turns on which kind it is.
 *
 * All three are on the record as well, each at the moment it arrived there, and
 * each is one card drawn twice rather than two cards.
 */
export type PinnedEvent = { "TaskList": TaskListEvent } | { "StageList": StageListEvent } | { "PullRequest": PullRequestEvent };

/**
 * The account a Profile names, in the shape the agent type running it keeps
 * one.
 *
 * Flat on the wire — `{"agent_type": "Claude", "claude_dir": "…",
 * "config_file": "…"}` — so the type is a field the viewer can read and narrow
 * on rather than a name it has to unwrap the account out of. Which is what the
 * form draws its fields off: a shape per type, and adding a backend adds a
 * variant here and the fields beside it.
 *
 * One shape for both directions. A Profile as the viewer receives it carries
 * the resolved paths the server recorded and a Profile as the human has just
 * written it carries what they typed, but they are the same fields either way,
 * and two types for one shape would be two opinions about what an account is.
 */
export type ProfileAccount = { "agent_type": "Claude", claude_dir: string, config_file: string, } | { "agent_type": "Codex", home: string, } | { "agent_type": "Grok", home: string, } | { "agent_type": "OpenCode", home: string, };

/**
 * Which Profile and model a Conversation is pairing for one of its roles.
 */
export type ProfileChoice = { profile_id: number, 
/**
 * One of that Profile's models. Never absent: there is no default model
 * anywhere, so a Pairing is picked whole or not at all.
 */
model: string, };

/**
 * What became of choosing one.
 */
export type ProfileChosen = "Chosen" | "NoSuchConversation" | "NoSuchProfile" | "NoSuchModel" | "NotDrafting";

/**
 * What became of removing a Profile.
 */
export type ProfileDeleted = "Removed" | "NoSuchProfile" | "InUse";

/**
 * A Profile as the human has just written it, for saving or for rewriting.
 *
 * The account says which type it is, because the fields beside it are that
 * type's. The form picks one from the types whose stage has landed — a type
 * that cannot launch the real binary yet would be a lie in a picker — so a
 * type this knows about may still be one nothing arrives as.
 */
export type ProfileEdit = { name: string, 
/**
 * The absolute paths this Profile's account is, in its type's shape.
 */
account: ProfileAccount, 
/**
 * The models this account can run a session on, in the order they were
 * typed. The form takes them a line apiece; blank lines and repeated
 * whitespace are the server's to drop, and a list that comes to nothing is
 * refused.
 */
models: Array<string>, };

/**
 * One row of the Profile list.
 *
 * The account's paths are the resolved ones the server recorded rather than
 * whatever was typed to save them: those are what will be bind-mounted, so
 * those are what is worth showing.
 */
export type ProfileEntry = { id: number, name: string, 
/**
 * Which agent this Profile runs, and the account it runs as — one field,
 * because the type is what says which fields the account has.
 */
account: ProfileAccount, 
/**
 * Every model this account can run a session on. At least one, and none of
 * them preferred over the others: the list says what is available and
 * nothing more.
 */
models: Array<string>, 
/**
 * `null` while the account is where it was left, which is the ordinary
 * case.
 */
broken: Broken | null, };

/**
 * What became of saving a Profile.
 *
 * The refusals are the server's and not the form's: the Watched Paths are a
 * security boundary, and every request reaching the endpoint is decided there
 * whether or not a form was involved.
 */
export type ProfileSaved = "Saved" | "NoSuchProfile" | "Nameless" | "Modelless" | "NameTaken" | "DirNotAbsolute" | "DirMissing" | "DirOutsideWatchedPaths" | "NotADirectory" | "ConfigNotAbsolute" | "ConfigMissing" | "ConfigOutsideWatchedPaths" | "NotAFile" | "HomeNotAbsolute" | "HomeMissing" | "HomeOutsideWatchedPaths" | "HomeNotADirectory";

/**
 * The grilling's closing proposal as the Set it rides draws it: which direction
 * was recommended, and why.
 *
 * The rationale arrives as HTML like every other piece of agent markdown on this
 * wire — the parser and the sanitizer are the server's.
 */
export type ProposalView = { 
/**
 * The direction the agent recommends, which the chooser marks.
 */
direction: Direction, 
/**
 * Why, rendered and sanitized by the server on the way out.
 */
rationale_html: string, };

/**
 * The agent's prose, rendered.
 */
export type Prose = { 
/**
 * The turn's place in the conversation, counted from 1 — what the viewer
 * reconciles rows by, so a fold opened on one survives a re-read.
 */
id: number, html: string, };

/**
 * One check GitHub is running against a pull request, as the details pane
 * receives it: what it is called, how it is getting on, and where its run is.
 *
 * A line of a list GitHub keeps, in the spirit [`PullRequestCommit`] is one:
 * read at the moment the pane is opened rather than written down, because a
 * suite is still running while the human is looking at it.
 */
export type PullRequestCheck = { 
/**
 * What GitHub calls it, which is what the human calls it by.
 */
name: string, how: Checked, 
/**
 * Where its run is, as GitHub gave it — the one thing a red check cannot
 * be read without. Empty where GitHub gave none, which is a check drawn as
 * its name and nothing to follow.
 */
link: string, };

/**
 * One comment on a pull request: who said it, when, and what they said.
 *
 * The body arrives rendered, like everything else an outsider wrote — a comment
 * is markdown, and it is markdown from the public internet, so it is sanitized
 * on this side of the wire rather than put in a page raw.
 */
export type PullRequestComment = { 
/**
 * The login of whoever left it. Empty where the account has gone, which is
 * a comment to draw rather than a reason to refuse the pane.
 */
author: string, 
/**
 * When it was made, RFC 3339, as GitHub stamped it.
 */
at: string, html: string, };

/**
 * One commit of a pull request: what it is, and what it was called.
 *
 * Not a [`CommitEvent`]: that is a commit Verkstead watched land on the branch
 * and put on the Timeline, with counts of what it moved and a diff behind it.
 * This is a line of a list GitHub keeps, and the two can differ — a branch that
 * was rebased after the PR opened has commits on the PR that are on no
 * Timeline.
 */
export type PullRequestCommit = { 
/**
 * The full hash, as everything on this wire carries one: the page shortens
 * it for reading.
 */
sha: string, 
/**
 * The first line of the commit message.
 */
subject: string, };

/**
 * What is on a pull request now: the commits it carries, what GitHub is running
 * against it, and what has been said about it.
 *
 * Its own request rather than a field on the Conversation, for the reason a
 * commit's diff is one — and for a further reason of its own: reading this is
 * asking GitHub, over the network, through the host's `gh`. A Timeline that
 * carried it would make an API call every time an open page heard the world
 * moved.
 *
 * Fetched rather than remembered, in the same spirit the task list is read off
 * the Worktree: a PR is being worked on while the human is looking at it.
 */
export type PullRequestDetails = { 
/**
 * Oldest first, as GitHub lists them, which is the order they landed.
 */
commits: Array<PullRequestCommit>, comments: Array<PullRequestComment>, 
/**
 * Every check GitHub is running against it, in the order GitHub lists
 * them. Empty where there are none, which is a repository with no CI.
 *
 * Each of them rather than the one word the card draws — see
 * [`CheckRollup`]. What the card has room for is which of the three a
 * suite is; this is the pane somebody opens to find out *which* check is
 * red and where its run is.
 */
checks: Array<PullRequestCheck>, };

/**
 * The pull request as the Timeline shows it: what it is called and what number
 * it answers to, with a way out to GitHub itself.
 *
 * An id and a stamp of its own, unlike the task list beside it, because a pull
 * request is the whole of what it says: the finish step opened one at a moment
 * worth keeping, and the Conversation moved into Wrapping on the strength of
 * it. What is not on the record is what the PR holds — see
 * [`PullRequestDetails`], which the details pane fetches when somebody opens
 * this.
 */
export type PullRequestEvent = { id: number, 
/**
 * When it reached the Timeline, RFC 3339 — which is when Verkstead found
 * it rather than when GitHub opened it, the two being a finish step apart.
 */
at: string, 
/**
 * The number GitHub gave it, which is what everybody calls it by.
 */
number: number, 
/**
 * Its title, which is the feature name the finish step gave it.
 */
title: string, 
/**
 * The whole URL, because merging is the human's act and this is the way to
 * where they do it.
 */
url: string, 
/**
 * Which repository it was opened in, where that is not the Conversation's
 * own.
 *
 * `None` is the work's own repository and draws nothing, by the rule a
 * commit's label follows: an unlabeled card means the repo the Conversation
 * is in, and the label earns its place when the pinned block holds a
 * companion's pull request as well.
 */
repo: string | null, 
/**
 * How the checks on it were getting on the last time anything asked, or
 * nothing where nothing has — a pull request in a repository with no CI,
 * and one opened before Verkstead started writing this down.
 *
 * The aggregate rather than the checks, because what the card has room for
 * is one icon: which of the three a suite is, and not what each of them is
 * called.
 *
 * It can be stale, and on a Conversation nothing is watching any more it
 * will be: what keeps it fresh is the checks watcher, and that stops when
 * the wrap-up is over.
 */
checks: CheckRollup | null, 
/**
 * And whether it merges into its base, as the last look at GitHub found it
 * — or nothing where nothing has looked.
 *
 * Beside the rollup because it is the same kind of fact: a reading of
 * GitHub written down when something asked, drawn as a mark on the card,
 * and stale on a Conversation nothing is watching. What keeps this one
 * fresh outlives the wrap-up, though — a sweep asks about a Done
 * Conversation's pull requests every quarter of an hour until each is
 * merged or closed.
 *
 * Unlike the rollup, a companion's card carries its own: whether a branch
 * conflicts with its base is a fact about that branch, and it is written
 * down per pull request rather than per Conversation.
 */
merging: Merging | null, };

/**
 * The public half of the server's VAPID keypair, base64url-encoded from the
 * uncompressed point — what `PushManager.subscribe` takes as its
 * `applicationServerKey`.
 *
 * The private half stays on the server: this is only how a browser names the
 * server it is subscribing to.
 */
export type PushKey = { key: string, };

/**
 * A turn put to the agent, rendered.
 */
export type Put = { 
/**
 * The turn's place in the conversation, counted from 1.
 */
id: number, html: string, };

/**
 * A Question Set as the Timeline shows it: what it was called, the table of
 * what was asked against what was decided, and where it stands.
 *
 * The table and not the Set. The design gives a Question Set a summary of
 * number, question and answer in the Timeline and the whole document in the
 * details pane, and the two are different sizes: a Set carries a Preface, every
 * Option of every Question and the whole uncommitted Diff of the repository it
 * was asked from, and the Timeline is re-read every time an open page hears the
 * world moved.
 *
 * `set_id` is what the details pane fetches the document by, through
 * `/api/ui/sets/{id}` — the Set's own id rather than this Event's, because a
 * Set answered anywhere is the same Set here.
 */
export type QuestionSetEvent = { id: number, 
/**
 * When the Set was put, RFC 3339.
 */
at: string, set_id: number, title: string, 
/**
 * One row per Question and Sub-question, in the order the agent asked
 * them.
 */
rows: Array<SetRow>, 
/**
 * Whether it is still waiting on the human, and what became of it if not.
 * The same verdict the Set's own sheet carries, from the same registry of
 * held waits — this is a Timeline the human answers from.
 */
standing: Standing, };

/**
 * One Question as the page draws it, with its Sub-questions nested one level
 * under it.
 */
export type QuestionView = { ask: AskView, subquestions: Array<AskView>, 
/**
 * Whether this Question is a Heading — Sub-questions under it and no
 * Options of its own — and so heads them rather than asking anything. The
 * page draws its text without a field, and no Answer comes back for it.
 *
 * Answered here rather than worked out in the browser from the Options and
 * Sub-questions beside it, so that the page and the grammar that refuses a
 * Response cannot come to different readings of the same Set.
 */
heading: boolean, 
/**
 * The Question's own text as plain words, for the line the table of
 * contents gives it.
 *
 * The nav cannot use `ask.text_html`: it is a line of text in a narrow
 * column, and the markup in there would have to be taken back out to get
 * the words — which means a parser on the browser's side of the wire, the
 * one thing rendering on the server is for. So the words travel beside the
 * HTML, rendered from the same markdown by the same pass.
 *
 * Sub-questions have none, because the nav does not list them.
 */
nav_text: string, };

/**
 * The agent's reasoning, rendered.
 */
export type Reasoning = { 
/**
 * The turn's place in the conversation, counted from 1.
 */
id: number, html: string, };

/**
 * What became of a registration.
 *
 * The refusals are the server's and not the form's: a check the browser made
 * is a courtesy, and every request reaching this endpoint is decided here
 * whether or not a form was involved.
 */
export type Registered = "Added" | "NotAbsolute" | "Missing" | "OutsideWatchedPaths" | "NotARepository" | "NoDefaultBranch" | "AlreadyRegistered";

/**
 * A repository the human is asking Verkstead to take on, named by its absolute
 * path.
 *
 * A path and nothing else: the name and the default branch are read off the
 * repository rather than claimed, for the same reason the CLI derives a Set's
 * `project` and `branch` instead of trusting them.
 */
export type Registration = { path: string, };

/**
 * One repository's block of a Set's Diff: what it is called, and its
 * uncommitted changes rendered as any other Diff is.
 *
 * The blocks come in the order they were composed in — the Conversation's own
 * repository first, then its read-write companions — and the anchors inside
 * them run on across the whole Diff, so `paths[0]` of the second block is
 * whichever `diff-n` the first one left off before.
 */
export type RepoDiffView = { 
/**
 * The repository's registered name, and `null` on the Conversation's own
 * repository drawn as the whole of the Diff: an unlabeled block *is* the
 * work's own repo, so saying it there would be saying it twice.
 *
 * A companion's block is named whether or not it is the only one — it is
 * somebody else's repository however little else is uncommitted that day —
 * which is the rule a commit card follows, asked the same way round.
 */
repo: string | null, diff: DiffView, };

/**
 * One row of the Repo list.
 *
 * The path is the resolved one the server recorded rather than whatever was
 * typed to register it: that is the directory Verkstead will actually work in,
 * so it is the one worth showing.
 */
export type RepoEntry = { id: number, name: string, path: string, default_branch: string, };

/**
 * What became of taking one off the registry.
 *
 * A removal rather than a deletion, which is why nothing here says anything
 * about a Timeline: every Conversation ever started on a Repo goes on naming
 * it, and what a removal changes is only what is offered for new work.
 *
 * Shaped like [`ProfileDeleted`](crate::ProfileDeleted), because it is the same
 * sentence about the other thing the settings page configures — and refused for
 * the same kind of reason.
 */
export type RepoRemoved = "Removed" | "NoSuchRepo" | "InUse";

/**
 * One registered Repo opened: everything the card cannot hold, read at the
 * moment it is asked for.
 *
 * The card's own three facts come along with it rather than being left to the
 * list behind the pane. The pane is a page of its own as far as a link is
 * concerned — somebody reloads on it, or arrives from a message — and a pane
 * that drew its own title out of another read would have nothing to say until
 * that read landed.
 *
 * Nothing here is stored beyond those three. The branches are git's own answer,
 * the counts are the store's, and the roadmaps are read off the repository the
 * way the notice under the new-conversation box reads them — so a branch
 * somebody pushed a minute ago is on this list, and a roadmap somebody has
 * since picked up is not.
 */
export type RepoView = { id: number, name: string, 
/**
 * The resolved path, which is the directory Verkstead will work in.
 */
path: string, 
/**
 * And what a Conversation branches from unless it is told otherwise.
 */
default_branch: string, 
/**
 * Every branch the repository has, local and remote-tracking both — the
 * same reading the base dropdown is filled from.
 */
branches: Array<string>, 
/**
 * How many Conversations are on this Repo and still going: everything that
 * is neither Done nor Closed, a Draft included.
 */
live: number, 
/**
 * And how many are over, which is Done and Closed together. The two are
 * counted apart because they are read for different reasons — what is on
 * this Repo now, and what has been.
 */
finished: number, 
/**
 * The roadmaps in it that nothing is driving, as the notice under the
 * new-conversation box finds them. Empty where there are none, which is
 * most repositories most days.
 */
roadmaps: Array<AbandonedRoadmap>, 
/**
 * How a conflicted pull request in this repository is resolved, where this
 * Repo has been told something other than what every other one does.
 *
 * `null` is *whatever the global setting says* rather than *merge*: the two
 * are the same answer today and stop being the same the moment the global
 * is changed, and a Repo that had quietly frozen this morning's global
 * would be a choice nobody made. What that global is, is on the settings
 * themselves — see [`crate::SettingsView::conflict_resolution`].
 */
conflict_resolution: ConflictResolution | null, };

/**
 * The **Resolve conflicts** press as the page receives it: when, and nothing
 * else.
 *
 * Nothing else because there is nothing else. Where it sends the work is always
 * Wrapping, which the move under it says; what it was about is the pull
 * requests the record says conflict, which the cards above it draw. The row is
 * the deciding, and the deciding is the whole of what it holds.
 *
 * So the words are the viewer's, as a move's are — see [`SteerEvent`], whose
 * sentence this one stands beside and must not be mistaken for.
 */
export type ResolveConflictsEvent = { id: number, 
/**
 * When it was pressed, RFC 3339.
 */
at: string, };

/**
 * What became of pressing **Resolve conflicts** on a finished Conversation's
 * pull request.
 *
 * Named the way [`Resumed`]'s refusals are, and for the same reason: the press
 * either sets a resolution going or it does not, and a button that quietly did
 * nothing would leave the human waiting on a session that was never dispatched.
 *
 * The refusals are of two kinds. Two of them are readings that have moved on
 * rather than anything for the human to correct — the button is drawn off the
 * record, and the record is what this is answered from — so each says what has
 * changed since the pane was drawn. The other two are about the checkout the
 * resolution session would work in, which a Conversation left Done for weeks is
 * the likeliest of any to have lost.
 */
export type Resolved = "Resolving" | "NoSuchConversation" | "NotDone" | "NothingConflicts" | "NowhereToWork" | "WorktreeRefused";

/**
 * The submitted collection of Answers and Unanswered markers for one Question
 * Set, plus an optional set-level comment — and, on a Set carrying a proposal,
 * the direction the human picked.
 *
 * The invariant is explicitness, not completeness: every Question and
 * Sub-question in the Set appears in `answers` one way or the other, so the
 * agent cannot silently miss a question the human left open. A Response whose
 * every entry is Unanswered carries no Answers at all — with a comment, that
 * is the counter-question that redirects the discussion.
 */
export type Response = { 
/**
 * One entry per Question and Sub-question in the Set.
 */
answers: Array<Answer>, 
/**
 * What the human wants to say about the Set as a whole.
 */
comment?: string | null, 
/**
 * How the human chose to have the work built, on the one Set that carries
 * a [`crate::set::Proposal`].
 *
 * A field of its own rather than an ordinary Answer, because it answers no
 * Question: the chooser is the viewer's, injected onto any Set carrying a
 * proposal, and the three directions it offers are the same three every
 * time. An Answer here would be a Question the agent never asked and would
 * have to be excluded from every rule that counts them.
 *
 * Picking is the whole of accepting the proposal. Every other way of
 * answering sends it back — an answer in the human's own words, questions
 * left open, anything without a pick — so `None` on a proposal Set is the
 * human disagreeing, and `None` anywhere else is every ordinary Response.
 */
direction?: Direction | null, 
/**
 * The human saying there is nothing else, on a Set asked while its
 * Conversation is in Follow-up.
 *
 * A field of the Response rather than an Answer for the reason
 * [`Response::direction`] is one: the control is the viewer's, injected
 * onto the Set's closing section, and it answers no Question anybody
 * asked.
 *
 * **The agent never sees it.** The mark comes off the Response on the way
 * into the store and is recorded beside it — see `verkstead_store`'s
 * `endings` — so what a waiting session is handed is byte for byte what it
 * would have been handed without one. How a follow-up ends is Verkstead's
 * business rather than the session's: the agent writes an ordinary
 * Postscript and reads an ordinary Response, and the ending is entirely
 * the system's.
 */
nothing_else?: boolean, };

/**
 * What became of pressing Resume.
 *
 * Named the way [`GrillingStarted`]'s refusals are, and for a reason of its
 * own on top of theirs: Resume is never silent. Either something is running —
 * which needs no announcement, the session showing up on the Timeline — or
 * nothing is, and the one place that can say why is the answer to the press.
 * A recompute that quietly found nothing to launch is exactly the failure this
 * whole feature is replacing.
 */
export type Resumed = "Resumed" | "NoSuchConversation" | "NotDriven" | "AlreadyDriven" | "NowhereToWork" | "WorktreeRefused" | "NoDirection" | "NothingToWork" | "NoGrillingPairing" | "NoImplementationPairing" | "NoFollowUpBrief";

/**
 * The roadmap opened: every stage brief of it, rendered.
 *
 * What the card cannot show, one level up from [`BacklogPane`] and built the
 * same way. A stage list's card is the entries — a number, a title and a box —
 * and each entry names a brief beside `ROADMAP.md` that says what the stage is
 * for. That is what this is: the briefs themselves, in the roadmap's own order.
 *
 * Its own request rather than a field on the Conversation, for the reason the
 * backlog's is one: a Timeline is read every time an open page hears the world
 * moved, and a roadmap is read whole when somebody opens it.
 *
 * Named by the roadmap rather than by the Conversation, which is the one place
 * this parts company with the backlog: a Worktree has one `.tasks/` and may
 * hold any number of roadmaps, so the card says which of them it is.
 */
export type RoadmapPane = { 
/**
 * The roadmap's directory under `docs/roadmaps/` — `mvp` — which is its
 * identity, and what the card named to open this.
 */
name: string, 
/**
 * `ROADMAP.md`'s own heading. Empty where it wrote none, which is when the
 * pane falls back to the name, exactly as the card does.
 */
title: string, 
/**
 * In the order the roadmap has them, which is the order they get worked in.
 */
stages: Array<StageDocument>, 
/**
 * Whether any of these briefs came out holding a Diagram, and so whether
 * the pane carries the client-side renderer at all — asked once of all of
 * them, as [`BacklogPane::diagrams`] is.
 */
diagrams: boolean, };

/**
 * Which Pairing one of a Conversation's roles runs under, or that it runs none.
 *
 * `null` is the row that runs no session: a picker that offers one offers it
 * beside the Pairings, so the one press that picks either sends the same body
 * — see [`PickedView`].
 */
export type RoleChoice = { pairing: ProfileChoice | null, };

/**
 * Which of a rule's two patterns something is about.
 */
export type RuleField = "Author" | "Body";

/**
 * One rule a save was turned down over, by where it stood in what was sent.
 *
 * By position rather than by content, because the row it names is the row the
 * human is looking at: what they typed is still in front of them, and a
 * refusal that described the rule instead would leave the page matching it up
 * against its own boxes.
 */
export type RuleRefused = { 
/**
 * Where it stood among the rules that were sent, counting from zero.
 */
rule: number, 
/**
 * Which of the two patterns is at fault, or `null` where the rule itself
 * is — a rule giving neither field is refused as a whole, and there is no
 * box to draw that at.
 */
field: RuleField | null, 
/**
 * Why, in words to put on the row. The regex engine's own for a pattern it
 * would not take, on one line: what draws this is a small box under a text
 * field, and the engine's message is a diagram across three or four.
 */
why: string, };

/**
 * One session's Screen: the grid its Capture leaves on a terminal.
 *
 * Not the bytes and not a picture of them — the escape sequences that would
 * paint the grid as it stands, which is what the terminal in the details pane
 * is fed. The server holds the terminal that decided them and hands over the
 * repaint; the browser's copy is a window onto that one rather than a second
 * opinion about it (ADR 0007).
 *
 * The size comes with it because a repaint means nothing without one: the same
 * sequences put a session's display in different places on a grid of a
 * different width.
 */
export type Screen = { repaint: string, columns: number, rows: number, };

/**
 * One stored Question Set as the browser receives it: the document where this
 * build can still read what was asked, and the record itself where it cannot.
 *
 * A tagged kind rather than a `SetView` with everything nulled out, because the
 * two are read for different things. One is a Set to answer or a decision to
 * read back; the other is a body nobody here can render, kept so that what was
 * asked is not lost — see [`UnreadableSet`]. A page that had to work out which
 * it was holding from a field being null would be a page that could draw a
 * sheet over a Set it cannot read.
 */
export type SetReading = { "Set": SetView } | { "Unreadable": UnreadableSet };

/**
 * One row of a Question Set's Timeline table: the number it answers to, what
 * was asked, and what was decided.
 *
 * Plain words in both columns rather than the rendered HTML the Set page draws.
 * A row is one line in a list of Events — the markup would have to come back
 * out to fit, which means a parser on the browser's side of the wire, the one
 * thing rendering on the server is for.
 */
export type SetRow = { 
/**
 * `Q7` for a Question, `Q7a` for a Sub-question.
 */
name: string, 
/**
 * Whether this row is a Sub-question, so the table can indent it under the
 * Question it belongs to.
 */
nested: boolean, 
/**
 * What was asked, as plain words.
 */
question: string, 
/**
 * What was decided, as plain words: the Option that was chosen, whatever
 * was written, or both. Empty where nothing was — a Question left open, a
 * Heading that asked nothing, or a Set still waiting on the human. Which of
 * those it is, the Set's `standing` says.
 */
answer: string, };

/**
 * One Question Set as the browser receives it.
 *
 * Everything the agent wrote — the Preface, every Question's and Sub-question's
 * text, every Option's, and the Postscript — arrives as HTML rather than as its
 * source, and so does the Diff: the server has the markdown parser and the diff
 * highlighter, and this way the browser needs neither.
 */
export type SetView = { id: number, 
/**
 * The Conversation this Set was asked from — where it lives, and what a
 * page reached by the Set's own id leads back to.
 *
 * It travels with the Set rather than being looked up beside it, because a
 * page opened from a push notification knows the Set and nothing else, and
 * a way back that arrived a moment later would be a page that briefly led
 * nowhere.
 */
conversation: number, title: string, project: string | null, branch: string | null, preface_html: string | null, 
/**
 * The uncommitted changes the Set was asked over, one block per repository
 * — see [`RepoDiffView`]. Empty where there were none, which is what leaves
 * the Diff off the page altogether.
 */
diff: Array<RepoDiffView>, questions: Array<QuestionView>, 
/**
 * What the agent closed the Set with, for the page to draw above the
 * set-level comment box. Rendered here like the Preface, because it is the
 * same kind of thing said at the other end of the Set.
 */
postscript_html: string | null, 
/**
 * Whether anything the agent wrote here came out as a Diagram, and so
 * whether this page carries the client-side renderer at all.
 *
 * Answered by the server, from the HTML it has just rendered — see
 * `diagrammed`. It travels with the Set because it is a fact about this
 * Set's own material, and because it decides what the page names in its
 * head, which is written before anything in the browser could ask.
 */
diagrams: boolean, 
/**
 * Where the Set stands. It decides whether this page is a form or a record,
 * so it travels with the Set rather than being fetched once the page is
 * already up.
 */
standing: Standing, 
/**
 * The wrap-up proposal this Set carries, on the one Set that carries one.
 *
 * What the page draws the direction chooser from: the recommendation to
 * mark, and the reasoning to put beside the three choices. `null` on every
 * ordinary Set, which is what leaves the chooser off it.
 *
 * It travels with the Set rather than being looked up beside it for the
 * reason the Conversation does: the decision and what it is a decision
 * about arrive together, so the page never draws the Questions above a
 * chooser that has not turned up yet.
 */
proposal: ProposalView | null, 
/**
 * Whether this Set was asked while its Conversation is in Follow-up, which
 * is what puts the Nothing-else option in its closing section.
 *
 * The other control the viewer injects, and it arrives the same way the
 * proposal does: with the Set, so the page never draws a closing section
 * the option turns up in a moment later.
 *
 * A fact about the Conversation rather than about the Set, which is why it
 * is decided here rather than read off the stored body. Nothing about what
 * was asked changes — an ordinary Set is what a follow-up's rounds are made
 * of — and a Set stored before any of this stays exactly as it was.
 */
follow_up: boolean, };

/**
 * The settings as the human has just written them.
 *
 * The author fields and the token travel together because the page saves as
 * one — and the token's half is an action rather than a value, because most
 * saves are not about the token at all.
 */
export type SettingsEdit = { git_author: Author, github_token: TokenEdit, 
/**
 * The build cache switch and size, as values rather than as an action:
 * there is nothing secret about either, so a save says where they are to
 * stand and the server writes that down.
 */
rust_build_cache: BuildCacheEdit, 
/**
 * And how a conflicted pull request is resolved where its Repo says
 * nothing, as a value for the same reason: there are two answers and a save
 * says which of them this is to be.
 */
conflict_resolution: ConflictResolution, 
/**
 * And whether Done shares the record to the pull request, as a value for
 * that reason too — a switch has two answers and a save says which of them
 * this is to be.
 */
share_on_done: boolean, 
/**
 * The Watched Paths the settings own, as values again: what is sent is
 * what `config.yaml` holds afterwards, so a row taken off the page is a
 * row taken out of the file.
 *
 * The installation's own are not here and cannot be sent. They are the
 * unit's word rather than this page's, and a save leaves them exactly
 * where they are — see [`PathSource`].
 */
watched_paths: Array<string>, 
/**
 * And the Sandbox Configuration binds the settings own, in the grammar
 * `--sandbox-bind` uses: `/abs/path` for a bind every sandbox gets, and
 * `name=/abs/path` for one the Repo registered under that name gets.
 *
 * Strings rather than a shape of their own, because a string is what the
 * file holds — and one grammar for both of the places a bind is said is
 * one thing to learn rather than two.
 */
sandbox_binds: Array<string>, 
/**
 * And what is to become of the ignore rules, which is an action rather
 * than a value — the one other field here that is.
 *
 * The token's half is an action because it is write-only. This one is
 * because it is the only setting a save can be *refused* over: a pattern
 * that will not compile is turned down, and a section that rode the rules
 * along as values would have the build cache's switch refused over a
 * pattern somebody hand-edited into the file weeks ago. So a save that is
 * not about the rules says nothing about them, and the ones on disk are
 * left exactly where they are.
 */
ignored_comments: IgnoredCommentsEdit, };

/**
 * What became of a save.
 *
 * One refusal to name, and it is the ignore rules' — see [`RuleRefused`].
 * There is nothing about a name, an address or a token this server declines to
 * write down, and a file it could not write at all is the other failure —
 * which is a status code rather than a named outcome, because it is something
 * to try again rather than something to read.
 */
export type SettingsSaved = { 
/**
 * How the settings stand now, read back off the files rather than echoed
 * from what came in — the files are the source of truth, and a hand-edit
 * made a moment ago is part of what the page should be showing.
 */
settings: SettingsView, 
/**
 * What GitHub made of the token that was just saved, or `null` where the
 * save was not about a token.
 */
verified: Verified | null, 
/**
 * The rules that would not be written down, or empty where the save
 * landed — which is every save that did not send any.
 *
 * A refusal here is the whole request refused: not one rule dropped and
 * the rest kept, and not the author written while the rules were turned
 * down. Neither file is touched, so `settings` above is how things stood
 * before the save as much as after it, and the page has one thing to do
 * with it — draw the errors at the rows and leave what the human typed
 * where it is.
 */
refused: Array<RuleRefused>, };

/**
 * The settings as they stand, read off the two files at the moment they are
 * asked for.
 */
export type SettingsView = { git_author: Author, 
/**
 * What can be said about the configured token, or `null` where there is
 * none — which is what a Verkstead nobody has told anything looks like.
 */
github_token: TokenSaved | null, 
/**
 * And how the shared Rust build cache stands.
 */
rust_build_cache: BuildCacheView, 
/**
 * And how a conflicted pull request is resolved in every Repo that has not
 * said otherwise.
 *
 * Never null, the way the build cache's switch is never null: nothing
 * configured is a merge, so what comes back is where the setting sits
 * rather than whether anybody has been here. A Repo's own override is on
 * the Repo — see [`crate::RepoView::conflict_resolution`].
 */
conflict_resolution: ConflictResolution, 
/**
 * And whether a Conversation's record is published and linked on its pull
 * request when the work settles to Done.
 *
 * Never null either, and false where nobody has said: this is the one
 * setting on the page whose unconfigured state is the off one, because
 * what it turns on writes to GitHub under the human's own account.
 */
share_on_done: boolean, 
/**
 * And the Watched Paths and the Sandbox Configuration binds, from both of
 * the places either of them is said.
 */
paths: PathsView, 
/**
 * And the comments nobody wants addressed, in the order they were written
 * down — empty on a Verkstead that has been told to ignore nothing, which
 * is the ordinary condition rather than a setting half made.
 *
 * Exactly as the file holds them, a pattern that will not compile
 * included: this is what the editor draws back into its rows, and a rule
 * quietly left out of the read would be one the human could not correct.
 */
ignored_comments: Array<IgnoreRule>, };

/**
 * What became of sharing a Conversation to the pull requests its work is on.
 *
 * One press is three acts — the file, the publish, and a comment on every pull
 * request the Conversation holds — so what comes back has to say how far it
 * got. The two ways it stops before saying anything anywhere are the publish's
 * own, carried in [`SharePublished`]'s words rather than said again here: a
 * share nobody could publish is a comment with no link in it, and there is
 * nothing to leave on a pull request.
 */
export type ShareCommented = { "Commented": { share: ShareView, on: Array<CommentedOn>, missed: Array<MissedOut>, } } | { "NotPublished": { why: SharePublished, } } | "NoPullRequest";

/**
 * What became of publishing a share: where it went, or why it did not go.
 *
 * A publish is Verkstead's own write to GitHub rather than a session's, and
 * every way it can fail is something for the human to go and do — which is why
 * each is named rather than folded into one refusal. Two of the three are about
 * the token on the settings page, and the page is where they are answered.
 */
export type SharePublished = { "Published": { share: ShareView, } } | "NoToken" | "NoGistScope" | { "Refused": { why: string, } };

/**
 * One published share, as the workbench draws it: the link, the gist behind it,
 * and the moment the snapshot was taken.
 */
export type ShareView = { 
/**
 * The page to send somebody to: the gist's id in the share viewer's
 * fragment, which is what draws the share as the conversation rather than
 * as source.
 *
 * Composed by the server on the way out rather than read off the record —
 * what the record holds is the gist as GitHub gave it, and which viewer a
 * reader goes through is a fact about the settings at the moment the page
 * is drawn. See `link` in `crates/server/src/sharing.rs`.
 */
url: string, 
/**
 * And the gist itself, as GitHub gave it, which is what the record holds and
 * what [`Self::url`] is composed from.
 *
 * Beside the viewer's link rather than instead of it, the two being for
 * different things: the viewer's is what a reader is sent, and this is where
 * the file actually is. A share is deleted at GitHub and nowhere else, so a
 * human who wants one gone has to be able to reach it.
 */
gist: string, 
/**
 * When it was published, RFC 3339 — drawn beside the link, because a link
 * with no date says nothing about how far the work has moved since.
 */
at: string, };

/**
 * One commit as a share carries it: the pane the workbench would have fetched,
 * beside the Event whose card opens it.
 */
export type SharedCommit = { 
/**
 * Which Timeline Event this is the pane of.
 *
 * The Event rather than the hash, because that is what the card opening it
 * is known by — and a Conversation works in more than one repository, so a
 * hash is not a name for one commit here either.
 */
id: number, 
/**
 * What the workbench's details pane draws: the Commit Summary rendered,
 * and the diff with every fold and every colour already in it.
 *
 * The endpoint's own rendering rather than a second one, so that a
 * colleague reading a patch and the human who reviewed it are reading one
 * drawing of it.
 */
pane: CommitPane, 
/**
 * Whether the repository still had the commit when the share was taken.
 *
 * `false` is a commit git can no longer show — rebased away, collected, or
 * in a repository that has moved out from under Verkstead — and the pane
 * says the diff is not in the file rather than that the commit changed
 * nothing. The workbench answers that case with a 404, which a share
 * cannot: one commit nobody can read is no reason to refuse the export of
 * everything around it, and what the Timeline says about it — the subject,
 * the hash, how much it moved — is on the card either way.
 */
held: boolean, };

/**
 * One Conversation as a share carries it, which is what the shared file boots
 * from.
 *
 * The Conversation whole rather than a shape of its own: the share is drawn by
 * the workbench's own components, so what they are handed has to be what they
 * are always handed. What differs is that this one has been through
 * [`shared`].
 */
export type SharedConversation = { 
/**
 * The record, curated — see [`shared`].
 */
conversation: ConversationView, 
/**
 * The sheet of every Question Set on that Timeline, in its order.
 *
 * Carried rather than fetched, which is the difference between a share and
 * the workbench: the live viewer asks for a Set when somebody opens one,
 * and a share has nothing to ask. So the whole of every Set the record
 * holds — the Preface, every Option of every Question, the Diff it was
 * asked over and what was decided — rides in the file, rendered by the
 * endpoint the workbench reads a Set through, so that a colleague's sheet
 * and the human's are one rendering of one decision.
 *
 * Read-only regardless of how a Set stood when the share was taken: what
 * makes it so is the sheet being drawn as a record — see the share's
 * details pane — because a Set still waiting on somebody is part of the
 * record too, and a reader with no server behind them cannot answer it.
 */
sets: Array<SetView>, 
/**
 * The pane behind every commit on that Timeline, in its order.
 *
 * Carried for the reason the sheets are: the workbench fetches a commit
 * when somebody opens one, and a share has nothing to fetch with. So the
 * whole of every one of them rides in the file — the Commit Summary
 * rendered, and the diff parsed, highlighted and folded per file.
 *
 * No cap on any of it, and nothing summarised on the way out. What a
 * colleague is being shown is the work, and a patch cut off at a size is
 * a different document from the one the human reviewed.
 */
commits: Array<SharedCommit>, 
/**
 * When the share was taken, RFC 3339.
 *
 * A share is a snapshot of a moment rather than a window onto a
 * Conversation that goes on moving, so the moment is on the file: the
 * reader is owed the date of the thing in their hands, and sharing again
 * makes another one rather than freshening this.
 */
exported_at: string, };

/**
 * Whether the sidebar is drawing what the human has archived.
 *
 * Their standing choice rather than this device's: it is read back off the
 * server on every load, and what is sent when the toggle is flipped is the
 * position it has been put in rather than the flip itself — a switch says
 * where it stands, and saying it twice says the same thing.
 */
export type ShowingArchived = { 
/**
 * On: the archived Conversations are on the list, in their ordinary
 * places. Off: they are not drawn at all.
 */
showing: boolean, };

/**
 * What the server says down a live Screen's socket.
 *
 * Watching a running session is the one place the viewer is sent something
 * rather than fetching it, so the two things it can be sent say which they are
 * rather than being told apart by shape. A repaint arrives first and whenever
 * the grid has been resized under everybody; what the session printed arrives
 * as it prints it.
 */
export type Shown = { "Painted": Screen } | { "Printed": string };

/**
 * How big a Screen is, in characters.
 *
 * Named for the Screen rather than for the window it was measured in, because
 * that is what it becomes: a watcher reports the size of the pane it drew, and
 * the latest one is the size the Screen and the session's own terminal are.
 */
export type Size = { columns: number, rows: number, };

/**
 * One stage's brief as the pane draws it: the entry it belongs to, and the
 * markdown of its file.
 */
export type StageDocument = { 
/**
 * As the roadmap writes it, zero-padding and all — `01`.
 */
number: string, title: string, 
/**
 * Whether the stage is finished, which here is the checkbox — see
 * [`StageEntry::done`]. Carried on the document because a finished stage
 * still has one: a brief stays where it is for ever, so the done state is
 * something the section says about itself rather than the reason it is
 * empty.
 */
done: boolean, 
/**
 * The brief rendered and sanitized, or `null` where there is nothing to
 * render. Unlike a task's, that is not the ordinary end of a stage's life
 * but a roadmap pointing at a file nobody wrote — which the pane says in
 * words rather than drawing a gap.
 */
html: string | null, };

/**
 * One stage of a roadmap: the number it answers to, what it is called, and
 * whether it is done.
 */
export type StageEntry = { 
/**
 * As the roadmap writes it, zero-padding and all — `01`.
 */
number: string, title: string, 
/**
 * Whether the stage is finished, which here *is* the checkbox: a stage's
 * brief stays where it is for ever, being the record of what the stage was
 * for, so there is no file going away to read it off. The other way round
 * from a task — see [`TaskEntry::done`].
 */
done: boolean, };

/**
 * The roadmap as the Timeline shows it: what it is called, and every stage
 * against whether it is checked.
 *
 * No id and no stamp of its own, for the reason the task list beside it has
 * none: it is read out of `docs/roadmaps/` each time the Conversation is, so
 * what it says is what the Worktree holds now. The moment the roadmap landed is
 * stamped all the same — see [`StageListReached`]. It opens, in both of the
 * places it is drawn, and what a details pane shows of it is not the list again
 * but the briefs its entries name — see [`RoadmapPane`], which is its own
 * request.
 */
export type StageListEvent = { 
/**
 * The roadmap's directory under `docs/roadmaps/` — `mvp` — which is its
 * identity: what a stage's brief sits beside, and what whoever starts the
 * next stage is pointed at.
 */
name: string, 
/**
 * `ROADMAP.md`'s own heading, which is prose the roadmap wrote about
 * itself. Empty where it wrote none.
 */
title: string, 
/**
 * In the order the roadmap has them, which is the order they get worked in.
 */
stages: Array<StageEntry>, };

/**
 * The roadmap on the record: where it landed, and what it says now.
 *
 * The stage lists rather than one, because a branch may have written to more
 * than one roadmap and the pinned block draws each of them. Empty where there
 * is nothing left to read, exactly as the backlog's is.
 */
export type StageListReached = { id: number, 
/**
 * When the roadmap landed, RFC 3339.
 */
at: string, roadmaps: Array<StageListEvent>, };

/**
 * How a Set stands: still waiting on the human, answered, or closed unanswered.
 */
export type Standing = { "Waiting": Liveness } | { "Answered": Answered } | { "LockedUnanswered": string };

/**
 * What became of starting one.
 */
export type Started = { "Started": { id: number, } } | "NoSuchRepo";

/**
 * Which of a companion's ways of not being delivered by a steer this was.
 *
 * [`CompanionRefusal`]'s four asked again at the other moment a companion is
 * checked out, and four more that only a steer can meet: the setup card
 * catches those the moment a row is pressed, and a steer is where the same
 * questions are asked past drafting, with nothing in front of them but the
 * submit.
 *
 * Two of the four are about the *set* rather than about git, and they come in
 * a pair because a steer does two things to it: an add is refused where the
 * Repo is a companion already, and an upgrade is refused where it is not one
 * yet — or where it is already as open as a companion gets.
 *
 * A vocabulary of its own rather than more variants of the grill start's, for
 * the reason [`SteerTarget`] is not [`crate::Lifecycle`]: what a grilling can
 * be refused for and what a steer can be refused for are different lists, and
 * one list would say each press can be refused for things it never could.
 */
export type SteerCompanionRefusal = "OwnRepo" | "AlreadyAdded" | "NotACompanion" | "AlreadyReadWrite" | "FetchFailed" | "NoBaseCommit" | "BranchExists" | "WorktreeRefused";

/**
 * A steer as the page receives it: when, where the human sent it, and what
 * they wrote to send it there with.
 *
 * The one Event that is sometimes a move and sometimes a document. A steer
 * into Wrapping or Done says nothing but the state, like the move it stands
 * above; a steer into Implementing carries the instruction the session was set
 * going on, and one into Follow-up the brief it was, which is the whole of what
 * that session was asked to do. A steer into Grilling carries a document too,
 * and that one arrives as a Brief Event of its own — it opens a round, and a
 * round starts from a Brief.
 */
export type SteerEvent = { id: number, 
/**
 * When it was steered, RFC 3339.
 */
at: string, 
/**
 * The state the human moved it into.
 */
target: Lifecycle, 
/**
 * The instruction they steered it with, rendered and sanitized on the way
 * out as every piece of markdown on this wire is — and `None` for every
 * steer that carried nothing written.
 */
html: string | null, };

/**
 * What clicking Steer found, which is what the modal it opens is drawn from.
 *
 * The click is a press of its own rather than the first half of the submit: it
 * stops the drive before the modal opens, so that nothing new is launched while
 * the human composes and the world the modal was drawn against is the world the
 * submit arrives in. Cancel leaves the Conversation stopped with Resume on
 * offer, which is accepted rather than a bug — the click is what freezes it.
 */
export type SteerOpened = { "Opened": { 
/**
 * Whether a session is still running as the modal opens.
 *
 * What **Interrupt current task** is offered for: the click leaves what
 * is running exactly where it is, and the checkbox is the only way to
 * end it where it stands. What ends it otherwise is the submit's own
 * launch — one Worktree holds one agent, so the session a steer starts
 * takes the Worktree from whatever is still in it — and into Done,
 * where nothing is launched, nothing ends it at all.
 *
 * Where nothing is running there is nothing to interrupt, so the
 * checkbox is not drawn at all.
 */
working: boolean, } } | "NoSuchConversation";

/**
 * What the human settled in the modal: where the Conversation goes, what runs
 * the work there, and what to do about anything still running.
 */
export type SteerSubmission = { 
/**
 * Which state to move it into.
 */
target: SteerTarget, 
/**
 * Whether to end the session that is running where it stands.
 *
 * `false` is the default and the ordinary case: the click stopped the
 * drive, so nothing was started after what is running, and what ends it is
 * this steer's own launch taking the Worktree from it. `true` is the human
 * saying they will not wait for it — which is what saves the wait where the
 * launch would have had to queue behind it, and what ends it at all into
 * Done, where nothing is launched.
 */
interrupt: boolean, 
/**
 * The Pairing the work runs under from here, for a target something runs
 * in — and what is picked is recorded as the *Conversation's*, because
 * steering re-settles what runs the work rather than picking for one
 * session.
 *
 * Absent where the target runs nothing, and absent where the human left
 * the picker on what the Conversation already had: both are a submit that
 * changes no Pairing. A Conversation with none fixed yet — a steered draft
 * — is why the pick is part of the modal rather than an error path, and one
 * that arrives with neither this nor a Pairing of its own is refused by
 * name.
 */
pairing: ProfileChoice | null, 
/**
 * The new round's Brief, for a steer into Grilling.
 *
 * It lands as a Brief Event of its own, frozen the moment it does: a Brief
 * freezes when its round leaves Draft, and a round steered into has no
 * Draft to leave. A second Brief beside the first rather than an edit of
 * it — what the earlier round was built from stays on the record.
 *
 * Absent is the ordinary case and not a refusal: the session starts on the
 * Brief that is already there, and the steer leaves nothing but its own
 * Event behind.
 */
brief: string | null, 
/**
 * The hand-written work, for a steer into Implementing.
 *
 * It lands as the Steer Event's own body and a session is started on it —
 * a driver of the Conversation rather than an errand beside it, so what
 * follows a clean finish is whatever the branch then holds.
 *
 * **Required where nothing stands to be carried on**, and optional beside
 * carrying on where something does: a branch with a backlog left in it has
 * an answer to what is next, and a branch with nothing on it has none. A
 * submit that names Implementing with neither is refused by name — see
 * [`ConversationSteered::NoInstruction`].
 *
 * Whitespace alone is nothing written, exactly as the brief above it: a
 * textarea somebody tabbed through is not an instruction.
 *
 * Nothing anywhere else reads it. A target that starts no session has
 * nothing to write an instruction for.
 */
instruction: string | null, 
/**
 * The brief, for a steer into Follow-up.
 *
 * It lands as the Steer Event's own body, exactly as the instruction above
 * it does, and the session started on it opens the follow-up: it answers
 * what the brief asks, does what it asks for, and asks the human what else
 * there is until they say there is nothing.
 *
 * **Required**, which is what makes it the one written payload with no
 * quiet meaning. Nothing on the branch could stand in for it — a follow-up
 * is not a step of the run to be picked up — so a submit that names
 * Follow-up without one is refused by name; see
 * [`ConversationSteered::NoFollowUpBrief`].
 *
 * Whitespace alone is nothing written, as everywhere else here.
 */
follow_up: string | null, 
/**
 * Whether the session is primed with everything the human has already
 * answered.
 *
 * The digest a relaunched grilling assembles for itself — every answered
 * Question Set of the Conversation, in the order it was asked — offered
 * here as a choice rather than always sent. A fresh brief is often the
 * point of the steer, and priming it with the whole of the last interview
 * would be steering into the argument that has just been left behind.
 *
 * Nothing anywhere else reads it: a target that starts no grilling starts
 * nothing to prime.
 */
digest: boolean, 
/**
 * The registered Repos to put into the sandbox the sessions to come run
 * in, each with what a setup row would have said about it.
 *
 * Sandbox setup rather than a property of one state, which is why it rides
 * every target work goes on in rather than one of them. Empty is the
 * ordinary case and the whole of what most steers carry.
 *
 * **Adding only.** Nothing here may name a companion the Conversation
 * already has — one that does is refused rather than obeyed, because the
 * frozen set only widens and what a session was once given is never taken
 * back mid-Conversation. Which is also why there is no list beside this
 * one for taking a companion away.
 *
 * Nothing anywhere else reads it: a target nothing runs in has no sandbox
 * to set up.
 */
added: Array<CompanionAddition>, 
/**
 * And the companions already there that the steer opens up: read-only
 * until now, read-write from here, each with what the branch cut in it is
 * called.
 *
 * **Upgrading only, which is why there is no mode on the rows.** Read-only
 * is not something this can ask for and neither is removal, so a
 * downgrade cannot be spelled here at all — what a session was once given
 * is never taken back mid-Conversation. Nothing here may name a companion
 * that is read-write already, or a Repo the Conversation has not got: both
 * are refused rather than obeyed, the first being a row with nothing left
 * to open and the second a page arguing with the record.
 *
 * Nothing anywhere else reads it, for [`Self::added`]'s reason: a target
 * nothing runs in has no sandbox to open up.
 */
upgraded: Array<CompanionUpgrade>, };

/**
 * Where a steer can send a Conversation.
 *
 * Draft and Closed are not among them and never will be: each has a way in of
 * its own, and a steer is for the states the work is *done in* — the four rungs
 * of the ladder, and Follow-up beside them, which has no other way in at all. A
 * target the modal offers is a target something can be set going in, which is
 * why the two that turn on a pull request are drawn out where there is none: an
 * instruction is writable anywhere and Done needs nothing, but there is no
 * wrapping up and no following up of work nobody can see.
 */
export type SteerTarget = "Grilling" | "Implementing" | "Wrapping" | "FollowUp" | "Done";

/**
 * What became of the human's Response.
 */
export type Submitted = "Accepted" | "AlreadyAnswered" | "NoSuchSet" | "Locked" | { "Rejected": Array<string> };

/**
 * What became of a device asking to be notified.
 */
export type Subscribed = "Stored" | "Incomplete";

/**
 * A subscription as `PushManager.subscribe` describes one, flattened to the
 * three things a push needs: where to send it, and the two keys it is
 * encrypted for.
 *
 * Flattened rather than passed through as the browser's own JSON, because the
 * nesting it uses — `keys.p256dh`, `keys.auth` — is the browser's shape and not
 * something the server has any reason to learn.
 */
export type Subscription = { endpoint: string, p256dh: string, auth: string, };

/**
 * One task's document as the pane draws it: the entry it belongs to, and the
 * markdown of its file.
 */
export type TaskDocument = { 
/**
 * As the list writes it, zero-padding and all — `01`, the same string the
 * card's entry carries.
 */
number: string, title: string, 
/**
 * Whether the task is finished, which is the entry's checkbox — see
 * [`TaskEntry::done`]. Carried on the document because a finished task
 * still has one: its file stays in `.tasks/` until the feature is over, so
 * the done state is something the section says about itself rather than the
 * reason it is empty. The same way round as a stage's — see
 * [`StageDocument::done`].
 */
done: boolean, 
/**
 * The document rendered and sanitized, or `null` where there is nothing to
 * render. Not the ordinary end of a task's life but the list pointing at a
 * file nobody wrote, which the pane says in words rather than drawing a
 * gap.
 */
html: string | null, };

/**
 * One task of a backlog: the number it answers to, what it is called, and
 * whether it is done.
 */
export type TaskEntry = { 
/**
 * As the list writes it, zero-padding and all — `01`. A Timeline that
 * renumbered the backlog would be showing its own list rather than the
 * repository's.
 */
number: string, title: string, 
/**
 * Whether the task is finished, which is the entry's own checkbox. That is
 * the done-signal the task runner turns on, and it is the list saying so
 * rather than anything the directory beside it happens to hold — a task
 * whose document has not been written yet is a task nobody has done.
 */
done: boolean, };

/**
 * The backlog as the Timeline shows it: what the work is called, and every
 * task against whether it is done.
 *
 * No id and no stamp of its own. It is read out of `.tasks/` each time the
 * Conversation is — the repository owns the files, and Verkstead never does —
 * so what it says is what the Worktree holds now rather than what it held at
 * any one moment.
 *
 * Which does not keep it off the record. The moment a backlog *landed* is worth
 * stamping and is stamped — see [`TaskListReached`], which carries this reading
 * at that row — so the identity is on the row and the content is here, and the
 * card is the same card in both places.
 *
 * It opens all the same, in both of the places it is drawn: what a details
 * pane shows of it is not the list again but the documents the entries name —
 * see [`BacklogPane`], which is its own request.
 */
export type TaskListEvent = { 
/**
 * What the backlog is called: `TODO.md`'s heading, which is the feature
 * name the breaking-down session picked. Empty where it wrote none.
 */
feature: string, 
/**
 * In the order the list has them, which is the order they get worked in.
 */
tasks: Array<TaskEntry>, };

/**
 * The backlog on the record: where it landed, and what it says now.
 *
 * The two halves come from different places on purpose. `id` and `at` are the
 * row's, stamped once when the branch first carried a backlog; `list` is the
 * Worktree's, read afresh every time the Conversation is — so the card ticks
 * along with the work while the row it sits at stays where it was.
 */
export type TaskListReached = { id: number, 
/**
 * When the backlog landed, RFC 3339.
 */
at: string, 
/**
 * The backlog as it stands, or nothing where there is none to read: a
 * Worktree that has been taken away, or a `.tasks/` the branch has since
 * finished with. The row stays either way — it is the record of a moment,
 * and the moment happened.
 */
list: TaskListEvent | null, };

/**
 * One entry in a Timeline.
 *
 * A tagged kind rather than a struct with a nullable field per kind: what the
 * details pane draws is decided by which kind an Event is, and the stages after
 * this one add their kinds here.
 */
export type TimelineEvent = { "Brief": BriefEvent } | { "Moved": MovedEvent } | { "AgentOutput": AgentOutputEvent } | { "QuestionSet": QuestionSetEvent } | { "UnreadableSet": UnreadableSetEvent } | { "Handoff": HandoffEvent } | { "Commit": CommitEvent } | { "Notice": NoticeEvent } | { "ManualTask": ManualTaskEvent } | { "Steer": SteerEvent } | { "ResolveConflicts": ResolveConflictsEvent } | { "PullRequest": PullRequestEvent } | { "TaskList": TaskListReached } | { "StageList": StageListReached };

/**
 * What is to become of the configured token.
 */
export type TokenEdit = "Keep" | { "Set": { token: string, } } | "Clear";

/**
 * Everything about the configured token that is not the token.
 */
export type TokenSaved = { 
/**
 * Its last four characters — fewer, for a token shorter than that, which
 * is a hand-edit rather than anything GitHub issued.
 */
last_four: string, 
/**
 * When the secrets file was last written, RFC 3339. The file's own
 * modification time rather than a stamp stored beside the token: the file
 * is the source of truth, and a hand-edit that moved the token would leave
 * a stored stamp saying the wrong day.
 */
at: string, };

/**
 * What a tool answered.
 */
export type ToolResult = { 
/**
 * The turn's place in the conversation, counted from 1.
 */
id: number, 
/**
 * The call this answers, by the name the backend gave it. Empty where the
 * log gave none, which leaves the answer standing on its own.
 */
call: string, 
/**
 * Whether the tool failed.
 */
failed: boolean, 
/**
 * What it said, as it said it.
 */
text: string, };

/**
 * A tool call, as one line plus what it was called with.
 */
export type ToolUse = { 
/**
 * The turn's place in the conversation, counted from 1.
 */
id: number, 
/**
 * What the tool is called.
 */
name: string, 
/**
 * The name the backend gave this call, which its answer names back. Empty
 * where the log gave none, which leaves the call with nothing to pair it
 * to — still a call, still shown.
 */
call: string, 
/**
 * The one line about it. Empty where the call said nothing this could
 * summarise, which leaves the name standing on its own.
 */
about: string, 
/**
 * What it was called with, whole.
 */
input: string, };

/**
 * One session's Transcript as the details pane receives it — the whole of it,
 * or whatever of it lies past where the pane's last reading stopped.
 */
export type TranscriptView = { 
/**
 * The conversation, in the order it happened.
 */
turns: Array<Turn>, 
/**
 * Everything that was not the conversation.
 */
bookkeeping: Array<Bookkeeping>, 
/**
 * Whether this is the record from its beginning, rather than a piece of it
 * to add to what the reader already has.
 *
 * The reader cannot tell from the payload and must not guess: a reading
 * that was asked to carry on from a cursor and could not falls back to the
 * whole record, which is always a correct answer — and appending one of
 * those to what was already drawn would be drawing the beginning twice.
 */
whole: boolean, 
/**
 * Where this reading stopped, to be handed back to ask for what comes
 * after it. Opaque to whoever holds it: it is the server's own bookmark,
 * and the shape of it is [`Cursor`]'s business alone.
 */
cursor: string, };

/**
 * One thing that was said, or done, or put.
 *
 * Flat on the wire — `{"id": 3, "kind": "Prose", "html": "…"}` — rather than
 * wrapped in the variant's name, because the viewer reconciles turns by `id`
 * and reconcile reads its key off the element itself: an id one level down
 * would match nothing and fall back to matching by position, silently.
 */
export type Turn = { "kind": "Prose" } & Prose | { "kind": "Reasoning" } & Reasoning | { "kind": "ToolUse" } & ToolUse | { "kind": "ToolResult" } & ToolResult | { "kind": "Put" } & Put | { "kind": "Unread" } & Unread;

/**
 * Something nothing here knows how to draw, in the conversation where it was
 * found: a block of an unknown type inside a turn, a line that is not JSON at
 * all, or one that does not say what type it is. A whole line whose type is
 * merely unknown is not one of these — it folds away as [`Bookkeeping`].
 */
export type Unread = { 
/**
 * The turn's place in the conversation, counted from 1.
 */
id: number, line: string, };

/**
 * A stored Set this build cannot deserialize, as the browser receives it: the
 * stored body, and what reading it came to.
 *
 * The body verbatim rather than rendered — there is nothing here that knows
 * what it means, which is the whole of what is wrong — so the page draws it as
 * the JSON it is. Nothing rewrites it: a later Verkstead that can read it again
 * should find it exactly as the agent sent it.
 *
 * No `standing` and no title. Answering is checked against Questions nobody
 * here can read, so it is not offered, and neither is locking; and what the
 * Set was called is in the body along with everything else, said once rather
 * than half-recovered into a heading.
 */
export type UnreadableSet = { id: number, 
/**
 * The Conversation it was asked from — the way back, which an unreadable
 * Set needs exactly as a readable one does.
 */
conversation: number, 
/**
 * The stored JSON, byte for byte.
 */
body: string, 
/**
 * What deserializing it said.
 */
why: string, };

/**
 * A Question Set the Timeline cannot draw a table for, because this build
 * cannot read the body it was stored as.
 *
 * What it carries is the reason and no more. There is no title — that is in the
 * body with everything else — and no standing, because a Set nobody here can
 * read is not one anybody is going to answer. The stored body itself is what
 * the details pane fetches, through the same `/api/ui/sets/{id}` a readable Set
 * is opened by: it is the same Set reached the same way, and what comes back
 * says which of the two it is.
 */
export type UnreadableSetEvent = { id: number, 
/**
 * When the Set was put, RFC 3339.
 */
at: string, set_id: number, 
/**
 * What deserializing the stored body said. On the row rather than behind
 * the fetch, because it is one line and it is the whole of what happened:
 * a reader who has to open the Event to find out why a row says nothing has
 * been told nothing by the row.
 */
why: string, };

/**
 * A device asking not to be told any more, named by its endpoint — which is the
 * only name a subscription has.
 *
 * An endpoint the server never stored is not an error: a browser can drop its
 * own subscription without the server having heard of it, and afterwards what
 * was asked for holds either way — nothing is sent there.
 */
export type Unsubscribe = { endpoint: string, };

/**
 * Whether there is a newer Verkstead to update to.
 */
export type UpdateNotice = "Current" | { "Available": { version: string, } };

/**
 * Who a token authenticates as, or why nobody could be asked.
 *
 * The failure is an answer here rather than a failed save. A token is pasted
 * once, out of a page on GitHub that will not show it again, and a network
 * that was briefly down is no reason to make the human go back for another
 * one: the token is written down, and this says what happened when it was
 * tried.
 */
export type Verified = { "Account": { login: string, 
/**
 * The scopes Verkstead needs that GitHub says this token has not been
 * given — empty on one that can do everything asked of it.
 *
 * `gist` is the whole of the list, and it is a list because the answer
 * is *what to go and tick*: publishing a share writes a secret gist,
 * which is Verkstead's own write to GitHub rather than a session's, and
 * a token issued for reading repositories does not carry it. The
 * scopes a *session* needs are not checked here — a session
 * authenticates as this token too, but what it does with it is the
 * repository's review process rather than anything this server asks
 * for.
 *
 * Empty as well where GitHub said nothing about scopes at all, which is
 * what a fine-grained token comes back as: it has permissions rather
 * than scopes, and reporting the absence of a header as a missing scope
 * would be sending the human to re-issue a token that works.
 */
missing: Array<string>, } } | { "Refused": { why: string, } };

/**
 * One way a Set fails the question grammar.
 */
export type Violation = { 
/**
 * The question at fault, e.g. `Q7` or `Q7a`. Absent when the problem is
 * the Set as a whole.
 */
label?: string | null, message: string, };

/**
 * One Watched Path, whichever of the two places said it.
 */
export type WatchedPathEntry = { 
/**
 * The directory: resolved, for the installation's own, which were resolved
 * when the server started; and exactly as it was written, for one out of
 * the settings — that is what a save sends back, so it has to come back as
 * it went in.
 */
path: string, source: PathSource, resolution: PathResolution, };

/**
 * And what a watcher says back up it.
 *
 * Two kinds of thing, each saying which it is: the socket is a conversation in
 * both directions, and what a watcher does to a Screen is look at it a
 * different size, or put something into it.
 */
export type Watching = { "Resized": Size } | { "PutIn": string };

/**
 * A Conversation's worktree: where it is, and whether it is still there.
 */
export type Worktree = { path: string, 
/**
 * Whether the directory has gone from under Verkstead.
 *
 * A thing to say rather than a thing to fail on later. A worktree is an
 * ordinary directory on a machine the human also uses, and one that has
 * been deleted by hand should read as a Conversation with a problem — not
 * as an obscure failure from whatever next tries to work in it.
 */
missing: boolean, };
